          "example": "2026-10-24 09:00:00"
        },
        {
          "type": "null"
        }
      ],
      "description": "Momentul verificării fișierului în UTC; null pentru fișiere neverificate."
    }
  },
  "required": [
    "state"
  ],
  "additionalProperties": false,
  "description": "Structura DocumentScanStatus. Exemplele sunt sintetice; permisiunile și stările reale se verifică la cerere."
}
```

Antete: `X-Request-ID`: Conform schemei., `RateLimit-Limit`: Conform schemei., `RateLimit-Remaining`: Conform schemei., `RateLimit-Reset`: Seconds until this rate window resets.

