```

### JavaScript

```javascript
const response = await fetch("https://openaliment.ro/api/v2/manage/documents/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa/scan", {
  method: "POST",
  credentials: "omit",
  headers: {
  "Accept": "application/json",
  "Authorization": "Bearer YOUR_ACCESS_TOKEN",
  "Content-Type": "application/json"
},
  body: JSON.stringify({})
});
const result = await response.json();
if (!response.ok) throw new Error(result.message || result.error_description || ('HTTP ' + response.status));
console.log(result);
```

### Python

